// Observe damage presentations generated by real native actions and signed HTTP
// checkpoints. No fake game state, damage injection, or shortened timer is used.
import assert from 'node:assert/strict';
import { once } from 'node:events';
import { mkdir, writeFile } from 'node:fs/promises';
import { createRequire } from 'node:module';
import { chromium } from 'playwright';

const require = createRequire(import.meta.url);
const { app, initialize } = require('../server/index.cjs');
const { createRecord, applyAction, sealRecord } = require('../server/replay.cjs');
const { readDecks } = require('./smoke.cjs');
const output = process.env.SWU_DAMAGE_REPORT || '/tmp/swu-damage-presentation';
await mkdir(output, { recursive: true });
await initialize();
const server = app.listen(0, '127.0.0.1');
await once(server, 'listening');
const origin = `http://127.0.0.1:${server.address().port}`;
const browser = await chromium.launch({ headless: true });
const contexts = [];
const report = { passed: false, assets: [], retaliation: [], chronology: [], durations: [], reducedMotion: null, resume: false, viewports: [], pageErrors: [] };
const damageSelector = '[data-damage-presentation]';
const playSelector = '[data-opponent-preview]';
const unit = (state, seat, name) => [...state.players[seat].ground, ...state.players[seat].space].find(card => card.name === name);
let fixture, page, view;

async function checkpoint({ exhaustDefender = false, vaderAttack = false } = {}) {
  const decks = readDecks();
  const vaderSeat = vaderAttack ? 'human' : 'bot', rebelSeat = vaderAttack ? 'bot' : 'human';
  fixture = await createRecord({ playerDeck: decks.find(deck => deck.id === (vaderAttack ? 'sor-darth-vader' : 'sor-luke-skywalker')), botDeck: decks.find(deck => deck.id === (vaderAttack ? 'sor-luke-skywalker' : 'sor-darth-vader')), difficulty: 'normal', seed: 1 });
  let state;
  const activeSeat = exhaustDefender ? 'bot' : 'human';
  for (let step = 0; step < 180; step++) {
    state = ['human', 'bot'].map(seat => fixture.game.view(seat)).find(candidate => candidate.prompt.active && candidate.legalActions.length);
    assert.ok(state, 'The fixture must always submit a legal native action.');
    const ready = [[rebelSeat, 'Consular Security Force'], [rebelSeat, 'Alliance X-Wing'], [vaderSeat, 'First Legion Snowtrooper']].every(([seat, name]) => unit(state, seat, name) && !unit(state, seat, name).exhausted);
    if (state.viewerId === activeSeat && state.prompt.stage === 'action' && ready && state.players[vaderSeat].leader.deployed && !state.players[vaderSeat].leader.exhausted) break;
    const own = state.players[state.viewerId];
    const names = state.viewerId === rebelSeat ? ['Consular Security Force', 'Alliance X-Wing'] : ['First Legion Snowtrooper'];
    let action;
    if (state.prompt.stage === 'initiative') action = state.legalActions.find(candidate => candidate.label === (state.viewerId === 'human' ? 'Yourself' : 'Opponent'));
    else if (state.prompt.stage === 'mulligan') action = state.legalActions.find(candidate => candidate.arg === 'keep');
    else if (state.prompt.stage === 'resource') {
      const candidates = state.legalActions.filter(candidate => candidate.type === 'card' && !state.prompt.selectedCardIds.includes(candidate.cardId) && !names.includes(candidate.label));
      action = (state.prompt.selectedCardIds.length < state.prompt.resourceSelection.max ? candidates[0] : null) || state.legalActions.find(candidate => candidate.arg === 'done');
    }
    else if (state.prompt.stage === 'action') {
      if (state.viewerId === vaderSeat && !own.leader.deployed && own.resourceCount >= 7) action = state.legalActions.find(candidate => candidate.cardId === own.leader.uuid && candidate.abilities?.some(ability => ability.type === 'deploy'));
      action ||= state.legalActions.find(candidate => candidate.intent === 'play' && names.includes(candidate.label) && !unit(state, state.viewerId, candidate.label));
      action ||= state.legalActions.find(candidate => candidate.arg === 'claimInitiative') || state.legalActions.find(candidate => candidate.arg === 'pass');
    } else action = state.legalActions.find(candidate => /^Deploy/.test(candidate.label)) || state.legalActions.find(candidate => candidate.arg === 'pass') || state.legalActions[0];
    assert.ok(action, `No native fixture action for ${state.prompt.title}`);
    await applyAction(fixture.record, fixture.game, action, state.viewerId);
    if (step === 179) assert.fail('The native fixture did not reach its ready combatants.');
  }
  if (exhaustDefender) {
    const defender = unit(state, 'bot', 'First Legion Snowtrooper');
    await applyAction(fixture.record, fixture.game, state.legalActions.find(action => action.cardId === defender.uuid), 'bot');
    state = fixture.game.view('bot');
    await applyAction(fixture.record, fixture.game, state.legalActions.find(action => action.cardId === state.players.human.base.uuid), 'bot');
  }
  state = fixture.game.view('human');
  if (vaderAttack) {
    const vader = unit(state, 'human', 'Darth Vader');
    const abilityTarget = unit(state, 'bot', 'Consular Security Force');
    const base = state.players.bot.base;
    await applyAction(fixture.record, fixture.game, state.legalActions.find(action => action.cardId === vader.uuid), 'human');
    state = fixture.game.view('human');
    await applyAction(fixture.record, fixture.game, state.legalActions.find(action => action.cardId === base.uuid), 'human');
    state = fixture.game.view('human');
    const action = state.legalActions.find(candidate => candidate.cardId === abilityTarget.uuid);
    assert.ok(action, 'Vader’s native On Attack ability must offer the real Consular Security Force target.');
    const result = { id: fixture.record.id, token: sealRecord(fixture.record), action, attacker: vader, defender: base, abilityTarget, vader };
    fixture.game.close(); fixture = null;
    return result;
  }
  const attacker = unit(state, 'human', 'Consular Security Force');
  const defender = unit(state, 'bot', 'First Legion Snowtrooper');
  const vader = unit(state, 'bot', 'Darth Vader');
  assert.equal(defender.exhausted, exhaustDefender);
  await applyAction(fixture.record, fixture.game, state.legalActions.find(action => action.cardId === attacker.uuid), 'human');
  state = fixture.game.view('human');
  const action = state.legalActions.find(candidate => candidate.cardId === defender.uuid);
  assert.ok(action, 'The genuine attack must allow the Snowtrooper target.');
  const result = { id: fixture.record.id, token: sealRecord(fixture.record), action, attacker, defender, vader };
  fixture.game.close(); fixture = null;
  return result;
}

async function newPage({ width = 375, height = 667, reducedMotion = 'no-preference' } = {}) {
  const context = await browser.newContext({ viewport: { width, height }, reducedMotion });
  contexts.push(context);
  const next = await context.newPage();
  next.setDefaultTimeout(25_000);
  next.on('pageerror', error => report.pageErrors.push(error.message));
  await next.addInitScript(() => {
    window.__damageTimeline = [];
    let last = '';
    const observe = () => {
      const damage = document.querySelector('[data-damage-presentation]');
      const play = document.querySelector('[data-opponent-preview]');
      const state = { damageIds: damage?.getAttribute('data-damage-event-ids') || '', damageType: damage?.getAttribute('data-damage-type') || '', playId: play?.getAttribute('data-preview-sequence') || '', playReady: play?.getAttribute('data-preview-ready') === 'true' };
      const key = JSON.stringify(state);
      if (key !== last) { window.__damageTimeline.push({ ...state, time: performance.now() }); last = key; }
    };
    document.addEventListener('DOMContentLoaded', () => new MutationObserver(observe).observe(document.body, { subtree: true, attributes: true, childList: true }));
  });
  return next;
}

async function clearSession() {
  if (!view?.sessionToken) return;
  const response = await fetch(`${origin}/api/games/${view.id}`, { method: 'DELETE', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ sessionToken: view.sessionToken }) });
  assert.equal(response.status, 204, await response.text());
  view = null;
}

async function resume(next, saved) {
  page = next;
  await page.goto(origin, { waitUntil: 'networkidle' });
  const asset = await page.locator('script[type="module"][src]').getAttribute('src');
  if (!report.assets.includes(asset)) report.assets.push(asset);
  await page.evaluate(({ id, token }) => { localStorage.setItem('swu-command-session', id); localStorage.setItem(`swu-command-state:${id}`, token); }, saved);
  await page.reload({ waitUntil: 'networkidle' });
  const pending = page.waitForResponse(response => response.url().endsWith(`/api/games/${saved.id}/state`));
  await page.getByRole('button', { name: 'Resume last game', exact: true }).click();
  const response = await pending;
  assert.equal(response.status(), 200, await response.text());
  view = await response.json();
  await page.locator('.prompt-panel[aria-busy="false"]').waitFor();
  assert.equal(await page.locator(damageSelector).count(), 0, 'Restoring an existing game must not replay its old damage.');
  assert.equal(await page.locator(playSelector).count(), 0);
}

async function attack(saved) {
  const previous = view;
  const pending = page.waitForResponse(response => response.url().endsWith(`/api/games/${view.id}/actions`) && response.request().method() === 'POST');
  pending.catch(() => {});
  await page.locator(`button[data-card-id="${saved.action.cardId}"]:visible`).first().click();
  const response = await pending;
  assert.equal(response.status(), 200, await response.text());
  view = await response.json();
  assert.deepEqual(view.warnings, []);
  const priorDamage = Math.max(0, ...(previous.publicDamageEvents || []).map(event => event.sequence));
  const priorPlay = Math.max(0, ...(previous.publicPlayEvents || []).map(event => event.sequence));
  return { damage: (view.publicDamageEvents || []).filter(event => event.sequence > priorDamage), plays: (view.publicPlayEvents || []).filter(event => event.sequence > priorPlay && event.playerId === 'bot') };
}

async function visibleDamage(event) {
  const locator = page.locator(`${damageSelector}[data-damage-event-ids*="${event.id}"]`);
  await locator.waitFor({ timeout: 30_000 });
  assert.equal(await locator.getAttribute('data-damage-type'), event.damageType);
  const token = locator.locator(`[data-damage-target-id="${event.targetCard.uuid}"][data-damage-amount="${event.amount}"]`);
  assert.ok(await token.count(), 'Actual damage and its target must be visible in the presentation.');
  assert.match(await token.first().innerText(), new RegExp(String(event.amount)));
  return locator;
}

async function blocked() {
  assert.equal(await page.locator('[data-game-content]').evaluate(element => element.inert), true);
  assert.equal(await page.locator('.prompt-panel').getAttribute('aria-busy'), 'true');
  let mutations = 0;
  const count = request => { if (request.method() === 'POST' && /\/api\/games\/[^/]+\/(actions|bot)$/.test(new URL(request.url()).pathname)) mutations++; };
  page.on('request', count);
  await page.keyboard.press('Escape');
  await page.keyboard.press('Enter');
  await page.keyboard.press('Space');
  await page.waitForTimeout(40);
  page.off('request', count);
  assert.equal(mutations, 0, 'Keyboard input during damage must never send a stale action.');
  assert.ok(await page.locator(damageSelector).count(), 'Escape must not cancel the damage presentation.');
}

async function layout(label) {
  const facts = await page.locator(damageSelector).evaluate(element => {
    const bounds = node => { const rect = node.getBoundingClientRect(); return { left: rect.left, right: rect.right, top: rect.top, bottom: rect.bottom, width: rect.width, height: rect.height }; };
    return { width: innerWidth, height: innerHeight, scrollWidth: document.documentElement.scrollWidth, scrollHeight: document.documentElement.scrollHeight, overlay: bounds(element), actors: [...element.querySelectorAll('[data-damage-card-id], [data-damage-amount]')].filter(node => node.getClientRects().length).map(bounds) };
  });
  assert.ok(facts.scrollWidth <= facts.width + 1 && facts.scrollHeight <= facts.height + 1, `${label}: page overflow ${JSON.stringify(facts)}`);
  for (const rect of [facts.overlay, ...facts.actors]) assert.ok(rect.left >= -1 && rect.right <= facts.width + 1 && rect.top >= -1 && rect.bottom <= facts.height + 1 && rect.width > 0 && rect.height > 0, `${label}: clipped damage presentation ${JSON.stringify(facts)}`);
  report.viewports.push({ label, ...facts });
}

async function completed(expected) {
  const timeout = expected.damage.length * 2000 + expected.plays.length * 5000 + 5000;
  await page.locator('.prompt-panel[aria-busy="false"]').waitFor({ timeout });
  assert.equal(await page.locator(damageSelector).count(), 0);
  assert.equal(await page.locator(playSelector).count(), 0);
  assert.equal(await page.locator('[data-game-content]').evaluate(element => element.inert), false);
  const timeline = await page.evaluate(() => window.__damageTimeline);
  assert.ok(timeline.every(item => !item.damageIds || !item.playId), 'Damage and opponent card reveals must not cover each other.');
  const starts = timeline.filter(item => item.damageIds);
  const actualIds = starts.flatMap(item => item.damageIds.split(','));
  assert.deepEqual(actualIds, expected.damage.map(event => event.id), 'Every real damage event must appear exactly once and in native order.');
  for (const start of starts) {
    const end = timeline.slice(timeline.indexOf(start) + 1).find(item => item.damageIds !== start.damageIds);
    assert.ok(end);
    const durationMs = Math.round(end.time - start.time);
    assert.ok(durationMs >= 1500 && durationMs < 2400, `Damage should remain readable for 1.6 seconds, received ${durationMs} ms.`);
    report.durations.push({ kind: start.damageType, eventIds: start.damageIds, durationMs });
  }
  const playStarts = timeline.filter(item => item.playId && item.playReady);
  for (const start of playStarts) {
    const end = timeline.slice(timeline.indexOf(start) + 1).find(item => item.playId !== start.playId || !item.playReady);
    assert.ok(end);
    const durationMs = Math.round(end.time - start.time);
    assert.ok(durationMs >= 2950 && durationMs < 5500, 'Opponent card reveals must retain their three-second display.');
    report.durations.push({ kind: 'opponent play', eventIds: start.playId, durationMs });
  }
  assert.deepEqual(playStarts.map(item => item.playId), expected.plays.map(event => event.id));
  const visualOrder = timeline.flatMap(item => item.damageIds ? item.damageIds.split(',') : item.playId && item.playReady ? [item.playId] : []);
  const nativeOrder = [...expected.damage, ...expected.plays].sort((a, b) => a.order - b.order).map(event => event.id);
  assert.deepEqual(visualOrder, nativeOrder, 'Opponent card reveals and damage must follow their shared native order.');
  return timeline;
}

async function verifyRetaliation(saved, received, label) {
  const damage = received.damage.find(event => event.damageType === 'combat' && event.targetCard.uuid === saved.attacker.uuid && event.sourceCard?.uuid === saved.defender.uuid);
  assert.ok(damage, 'Combat must attribute retaliation to the actual defending Snowtrooper.');
  assert.equal(damage.amount, 2, 'The Snowtrooper deals its printed two power in return, even when exhausted.');
  const overlay = await visibleDamage(damage);
  assert.ok(await overlay.locator(`[data-damage-card-id="${saved.defender.uuid}"]`).count());
  assert.equal(await overlay.locator(`[data-damage-card-id="${saved.vader.uuid}"]`).count(), 0, 'The nearby Vader must never be credited for another unit’s return damage.');
  assert.ok(await overlay.locator('[data-damage-direction="return"]').count(), 'Return damage needs an explicit reverse direction.');
  assert.match(await overlay.innerText(), /Defender deals damage back/i, 'The return hit must be explained in readable text.');
  await blocked();
  await page.waitForTimeout(450);
  await layout(label);
  await page.screenshot({ path: `${output}/${label}.png` });
  report.retaliation.push({ defender: saved.defender.name, exhausted: saved.defender.exhausted, amount: damage.amount, sourceCorrect: true });
  return overlay;
}

try {
  const ready = await checkpoint();
  await resume(await newPage(), ready);
  const first = await attack(ready);
  await verifyRetaliation(ready, first, 'retaliation-portrait');
  await completed(first);
  const completedCheckpoint = { id: view.id, token: view.sessionToken };
  await page.reload({ waitUntil: 'networkidle' });
  const pending = page.waitForResponse(response => response.url().endsWith(`/api/games/${completedCheckpoint.id}/state`));
  await page.getByRole('button', { name: 'Resume last game', exact: true }).click();
  const response = await pending;
  view = await response.json();
  await page.locator('.prompt-panel[aria-busy="false"]').waitFor();
  assert.equal(await page.locator(damageSelector).count(), 0);
  assert.equal(await page.locator(playSelector).count(), 0);
  await page.waitForTimeout(1800);
  assert.equal(await page.locator(damageSelector).count(), 0);
  report.resume = true;

  await clearSession();
  const exhausted = await checkpoint({ exhaustDefender: true });
  await resume(await newPage({ width: 844, height: 390 }), exhausted);
  const second = await attack(exhausted);
  await verifyRetaliation(exhausted, second, 'retaliation-landscape');
  await completed(second);

  await clearSession();
  const vader = await checkpoint({ vaderAttack: true });
  await resume(await newPage({ width: 1440, height: 900 }), vader);
  const vaderExchange = await attack(vader);
  const ability = vaderExchange.damage.find(event => event.damageType === 'ability' && event.sourceCard?.uuid === vader.vader.uuid && event.targetCard.uuid === vader.abilityTarget.uuid);
  const combat = vaderExchange.damage.find(event => event.damageType === 'combat' && event.sourceCard?.uuid === vader.vader.uuid && event.targetCard.uuid === vader.defender.uuid);
  assert.equal(ability?.amount, 2, 'Vader’s native On Attack ability must deal exactly two damage.');
  assert.equal(combat?.amount, 5, 'Vader’s separate base attack must deal its native five combat damage.');
  assert.equal(ability.attack?.id, combat.attack?.id);
  assert.ok(ability.order < combat.order);
  const abilityOverlay = await visibleDamage(ability);
  assert.equal((await abilityOverlay.getAttribute('data-damage-event-ids')).includes(combat.id), false, 'Vader’s ability must not merge into the later combat impact.');
  assert.match(await abilityOverlay.innerText(), /Ability damage/i);
  await page.waitForTimeout(450);
  await layout('vader-ability-desktop');
  await page.screenshot({ path: `${output}/vader-ability-desktop.png` });
  const combatOverlay = await visibleDamage(combat);
  assert.equal((await combatOverlay.getAttribute('data-damage-event-ids')).includes(ability.id), false);
  assert.match(await combatOverlay.innerText(), /Combat damage/i);
  await page.waitForTimeout(450);
  await page.screenshot({ path: `${output}/vader-combat-desktop.png` });
  await completed(vaderExchange);
  report.chronology.push({ source: vader.vader.name, abilityDamage: ability.amount, combatDamage: combat.amount, separatePresentations: true, orderPreserved: true });

  await clearSession();
  await resume(await newPage({ reducedMotion: 'reduce' }), ready);
  const reduced = await attack(ready);
  const returnDamage = reduced.damage.find(event => event.targetCard.uuid === ready.attacker.uuid && event.sourceCard?.uuid === ready.defender.uuid);
  const reducedOverlay = await visibleDamage(returnDamage);
  await page.waitForTimeout(150);
  const moving = await reducedOverlay.evaluate(element => element.getAnimations({ subtree: true }).filter(animation => animation.playState === 'running').map(animation => animation.animationName || animation.id));
  assert.deepEqual(moving, [], 'Reduced motion must retain readable damage without movement animations.');
  await layout('reduced-motion-portrait');
  await page.screenshot({ path: `${output}/reduced-motion-portrait.png` });
  await completed(reduced);
  report.reducedMotion = { readable: true, noMovingAnimations: true, durationPreserved: true };

  assert.deepEqual(report.pageErrors, []);
  report.passed = true;
  await writeFile(`${output}/report.json`, JSON.stringify(report, null, 2));
  console.log(JSON.stringify(report, null, 2));
} catch (error) {
  report.failure = error.stack;
  await writeFile(`${output}/report.json`, JSON.stringify(report, null, 2));
  if (page) await page.screenshot({ path: `${output}/failure.png` }).catch(() => {});
  throw error;
} finally {
  fixture?.game.close();
  await clearSession().catch(() => {});
  for (const context of contexts) await context.close();
  await browser.close();
  await new Promise(resolve => server.close(resolve));
}
